INSERT INTO BUNGU_TABLE VALUES('0101-00201-047', '絵筆　丸筆　14号（大）　ZBNR-14　1箱（10本入）', 10, '箱', 2822, '002', '独自の製法による特殊素材（ナイロン繊維）を使用した、最適なコシと水含みのバランスのとれた絵筆です。●穂先のまとまりがよく、毛抜けに強くなっています。●軸はプラスチック製で、腐食やカビの心配が無く、手入れが簡単です。●転がり防止、すべり止め付きで使いやすくなっています。●アクリル系絵の具にも使用できます。（穂先が乾く前に洗浄してください。）', 'img/bungu/0101-00201-047.jpg', '筆', '-', 'ZBNR-14', '軸径12mm×190mm', '穂先：ナイロン繊維、軸・前軸：再生PP', '【返品について】ご購入の際は、ご利用ガイド「返品・交換について」を必ずご確認の上、お申し込みください。');
