INSERT INTO BUNGU_TABLE VALUES('0107-00201-189', '貼ってはがせる養生テープ　半透明　1巻', 1, '巻', 236, '002', 'テラオカ×アスクルの養生テープ!一流メーカー、オラオラ製造の確かな品質でダントツの安さ!手切れの良さを実現しながらも、はがす時に途中で切れにくい基材を使用しています。', 'img/bungu/0107-00201-189.jpg', 'テープ', '-', '4100', '幅50mm×長さ25m', '基材：ポリエチレンクロス、粘着剤：アクリル系、巻芯：古紙パルプ100%', 'この製品は養生テープですので、ダンボール封緘、荷造り用の使用は避けてください。被着体の水・ゴミなどは充分取り除いてからご使用ください。皮フに直接貼らないでください。【返品について】ご購入の際は、ご利用ガイド「返品・交換について」を必ずご確認の上、お申し込みください。');
INSERT INTO BUNGU_TABLE VALUES('0107-00201-190', '重ね貼りできるクラフトテープ　白　0524　1巻', 1, '巻', 170, '002', '重ね貼りできるオリジナルクラフトテープ。巻芯は古紙100%を使用しています。テープの上に油性ペンで文字も書けます。引っ張りに強いクルパック加工。', 'img/bungu/0107-00201-190.jpg', 'テープ', '-', '-', '幅50mm×長さ50m', 'クラフト紙(クルパック加工)、巻芯：古紙パルプ配合率100%', '1箱(50巻入)につきテープカッターが2個付属します。クルパック加工とは紙に微細なしわをつけて縮ませ、のびを大きくして紙の引っ張り強度を高める加工です。【返品について】ご購入の際は、ご利用ガイド「返品・交換について」を必ずご確認の上、お申し込みください。');
